import logging
from .collector_factory import RemoteCommandCollectorFactory, LocalCommandCollectorFactory
# from .factory import Factory
from taf.collectors.core.entities.configurable_command_collector import \
    ConfigurableCommandCollector, ConfigurableStartableCommandCollector

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ConfigurableCommandCollectorFactoryBase(object):

    _product_class = ConfigurableCommandCollector
    _mandatory_parameters = {'find_command'}
    _optional_parameters = {'map_command', 'postprocess_command', 'cleanup_command'}


class ConfigurableCommandCollectorFactory(ConfigurableCommandCollectorFactoryBase,
                                          RemoteCommandCollectorFactory):
    pass


class ConfigurableLocalCommandCollectorFactory(ConfigurableCommandCollectorFactoryBase,
                                               LocalCommandCollectorFactory):
    pass


class ConfigurableStartableCommandCollectorFactoryBase(object):

    _product_class = ConfigurableStartableCommandCollector
    _mandatory_parameters = {'start_command', 'stop_command'}


class ConfigurableStartableCommandCollectorFactory(ConfigurableStartableCommandCollectorFactoryBase,
                                                   ConfigurableCommandCollectorFactory):
    pass


class ConfigurableStartableLocalCommandCollectorFactory(ConfigurableStartableCommandCollectorFactoryBase,
                                                        ConfigurableLocalCommandCollectorFactory):
    pass


class ConfigurableCommandCollectorFactorySelector(object):

    def create(self, configuration, existing_arguments):
        if "start_command" in configuration and "executor" in configuration:
            return ConfigurableStartableCommandCollectorFactory().create(configuration, existing_arguments)
        elif "start_command" in configuration:
            return ConfigurableStartableLocalCommandCollectorFactory().create(configuration, existing_arguments)
        elif "executor" in configuration:
            return ConfigurableCommandCollectorFactory().create(configuration, existing_arguments)
        else:
            return ConfigurableLocalCommandCollectorFactory().create(configuration, existing_arguments)
